summary:
Проверки прошли, но перед публикацией исправляю два пограничных случая, выявленных при ревью: отмена свайпом должна читаться синхронно даже до React-render, а очистка финализации не должна создавать необработанный rejected Promise. После правки повторю весь набор проверок.

```json
{"version":1,"taskId":"8a0be3a8-0a9f-4632-89a1-42d645506940","commandId":"fix-audio-races-11","operation":"run","headSha":"a4bf6e68d1ec87f6ea1faaf321505c380d437763","command":"python3 - <<'PY'
from pathlib import Path

recorder = Path('apps/mobile/src/audio/recorder.ts')
text = recorder.read_text()
old = """  void promise.finally(() => {
    if (finalizingPromise === promise) finalizingPromise = null;
  });
"""
new = """  void promise.then(
    () => {
      if (finalizingPromise === promise) finalizingPromise = null;
    },
    () => {
      if (finalizingPromise === promise) finalizingPromise = null;
    },
  );
"""
assert text.count(old) == 1
recorder.write_text(text.replace(old, new))

button = Path('apps/mobile/src/components/HoldToRecordButton.tsx')
text = button.read_text()
replacements = [
    (
        """  const recordingStartedAt = useRef(0);
  const recordingReady = useRef(false);
""",
        """  const recordingStartedAt = useRef(0);
  const recordingReady = useRef(false);
  const cancelledRef = useRef(false);
""",
    ),
    (
        """    recordingReady.current = false;
    setIsCancelled(false);
    setIsRecording(true);
""",
        """    recordingReady.current = false;
    cancelledRef.current = false;
    setIsCancelled(false);
    setIsRecording(true);
""",
    ),
    (
        """  const handleMove = (event: GestureResponderEvent): void => {
    if (!isRecording) return;
    setIsCancelled(startX.current - event.nativeEvent.pageX > CANCEL_DISTANCE);
  };
""",
        """  const handleMove = (event: GestureResponderEvent): void => {
    if (!isRecording) return;
    const shouldCancel = startX.current - event.nativeEvent.pageX > CANCEL_DISTANCE;
    cancelledRef.current = shouldCancel;
    setIsCancelled(shouldCancel);
  };
""",
    ),
    (
        """    recordingReady.current = false;
    if (isCancelled) {
      await cancelRecording();
      setIsCancelled(false);
      return;
    }
""",
        """    recordingReady.current = false;
    if (cancelledRef.current) {
      cancelledRef.current = false;
      await cancelRecording();
      setIsCancelled(false);
      return;
    }
""",
    ),
    (
        """    } finally {
      setIsCancelled(false);
    }
""",
        """    } finally {
      cancelledRef.current = false;
      setIsCancelled(false);
    }
""",
    ),
]
for old, new in replacements:
    assert text.count(old) == 1, old
    text = text.replace(old, new)
button.write_text(text)
